window.SAP_CH_DATA = {"id":"ch_42","title":"Tạo Reservation","start_page":411,"end_page":414,"slides":[{"page":411,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n3\nWM.05B.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nNGUYÊN LIỆU/BTP SƠ CHẾ TỪ KHO XƯỞNG VỀ KHO NGUYÊN LIỆU (IM – WM: CÓ \nBARCODE)\nWM.05B.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY CÓ BARCODE – CHUYỂN NGUYÊN LIỆU TỪ KHO XƯỞNG VỀ KHO NGUYÊN LIỆU (IM – WM: CÓ BARCODE)\nBộ phận kế hoạch\nBộ phận kho nguyên liệu\nBắt đầu\nKết thúc\nYêu cầu \nchuyển kho\nBước 13:\nXe nâng quét vị trí và xác \nnhận \nAPP: Putaway\nBước 11:\nXe nâng quét ID Pallet và ID \nhàng để điều chuyển vị trí \nAPP: Putaway\nBước 1:\nTạo phiếu yêu cầu chuyển \nkho\nAPP: Manage Reservation\nBước 2:\nĐưa hàng về vùng đệm\nBước 12:\nNâng hàng vào vị trí\nBước 7:\nKiểm tra giao dịch tự động \nchuyển kho\nAPP: Quản lý giao dịch \nBarcode\nBước 14:\nKiểm tra giao dịch tự động \nPutaway\nAPP: Quản lý giao dịch \nBarcode\nBước 6:\nQuét ID Pallet/ID hàng và \nthực hiện chuyển kho\nAPP: Chuyển kho\nBước 3:\nIn ID hàng\nApp: In nhãn ID hàng\nBước 4:\nIn nhãn ID Pallet (nếu có)\nApp: In nhãn ID pallet\nBước 5:\nDán nhãn ID hàng và \nID Pallet\nPhiếu nhập \nchuyển kho\nPallet chưa có nhãn\nNhãn ID pallet được in sẵn\nvà gắn định danh vào Pallet\nLệnh nhập \nchuyển kho\nBước 8:\nDựa vào chiến lược nhập \nhàng, SAP tự động chỉ định vị \ntrí nhập và đưa vào vị trí\nBước 9:\nNhân viên kho lấy tấm \nmica vị trí và gán vào \npallet\nBước 10:\nDựa vào tấm mica, xe \nnâng kéo hàng vào vị \ntrí\nChỉ định vị \ntrí?\nCó\nKhông","images":[]},{"page":412,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n4\n✓Tạo phiếu yêu cầu chuyển kho\n❑App thực hiện: Manage Manual Reservation\nBước 1:\nNhập app: “Manage Manual \nReservation” vào thanh tìm \nkiếm\nBước 2: \nClick chọn vào app Manage \nManual Reservation\nWM.05B.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nNGUYÊN LIỆU/BTP SƠ CHẾ TỪ KHO XƯỞNG VỀ KHO NGUYÊN LIỆU (IM – WM: CÓ \nBARCODE)","images":[""]},{"page":413,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n5\n✓Tạo phiếu yêu cầu chuyển kho\nBước 3:\nNgười dùng nhấn nút Create \nReservation \nBước 4: \nNgười dùng điền các thông \ntin sau\nMovement Type: Loại giao \ndịch\nPlant: Nhà máy \nBase Date: Ngày yêu cầu\nBước 5: \nSau khi hoàn thành Bước 4, \nnhấn Create để sinh ra số \nphiếu yêu cầu\n❑App thực hiện: Manage Manual Reservation\nWM.05B.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nNGUYÊN LIỆU/BTP SƠ CHẾ TỪ KHO XƯỞNG VỀ KHO NGUYÊN LIỆU (IM – WM: CÓ \nBARCODE)","images":["",""]},{"page":414,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n6\n✓Tạo phiếu yêu cầu chuyển kho\nBước 6:\nNgười dùng điền các thông \ntin sau đây\nReceiving Storage Localtion: \nKho nhận\nMaterial: Mã hàng\nQuantity: Số lượng\nStorage Location: Kho xuất\nBatch: Lô\nBước 7: \nSau khi hoàn thành Bước 6, \nnhấn Create để tạo ra phiếu \nyêu cầu\n❑App thực hiện: Manage Manual Reservation\nWM.05B.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nNGUYÊN LIỆU/BTP SƠ CHẾ TỪ KHO XƯỞNG VỀ KHO NGUYÊN LIỆU (IM – WM: CÓ \nBARCODE)","images":[""]}]};